NO_SESSION_MINUTES = 30
SESSION_EXPIRY_HOURS = 24
RECHECK_AFTER_MINUTES = 2
RELEASE = 'UPDATE product_variants SET ReservedQty = GREATEST(0, ReservedQty - (SELECT COALESCE(SUM(i.Qty), 0) FROM order_items AS i WHERE i.VariantId = product_variants.Id AND i.OrderId IN (SELECT Id FROM #stale))), UpdatedAt = SYSUTCDATETIME() WHERE Id IN (SELECT VariantId FROM order_items WHERE OrderId IN (SELECT Id FROM #stale)) AND EXISTS(SELECT 1 FROM products AS p WHERE p.Id = product_variants.ProductId AND p.TrackInventory = 1);'
parts = ['SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRANSACTION;', 'CREATE TABLE #stale (Id int PRIMARY KEY);', 'DELETE FROM #stale;', "INSERT INTO #stale SELECT Id FROM orders WHERE Status = 'pending' AND PaymentStatus = 'unpaid' AND CreatedAt < DATEADD(minute,-" + str(NO_SESSION_MINUTES) + ',SYSUTCDATETIME());', "INSERT INTO #stale SELECT o.Id FROM orders AS o WHERE NOT EXISTS(SELECT 1 FROM #stale s WHERE s.Id=o.Id) AND o.Status = 'pending' AND o.PaymentStatus = 'pending' AND o.CreatedAt < DATEADD(hour,-" + str(SESSION_EXPIRY_HOURS) + ',SYSUTCDATETIME());', RELEASE, "UPDATE payments SET Status = 'expired', UpdatedAt = SYSUTCDATETIME() WHERE OrderId IN (SELECT Id FROM #stale) AND Status = 'pending';", "INSERT INTO order_events (OrderId, Type, Message, CreatedBy) SELECT Id, 'status', 'Cancelled by reconciliation: payment not completed in time; reservation released', 'system' FROM #stale;", "UPDATE orders SET Status = 'cancelled', PaymentStatus = 'failed', CancelledAt = SYSUTCDATETIME(), UpdatedAt = SYSUTCDATETIME() WHERE Id IN (SELECT Id FROM #stale);", 'COMMIT TRANSACTION;', 'DROP TABLE IF EXISTS #stale;', "SELECT TOP 1 o.Id, o.Reference, o.Email, o.Name, o.Surname, o.Currency, o.SubtotalCents, o.ShippingCents, o.TaxCents, o.TotalCents, o.Status, o.PaymentStatus, o.FulfillmentStatus, o.PaidAt, o.CreatedAt, o.ShippingAddressJson, p.Id AS PaymentRowId, p.ConnectPaymentId, p.Status AS PaymentRowStatus, p.PaymentUrl, (SELECT i.Title AS [Title], i.VariantTitle AS [VariantTitle], i.Sku AS [Sku], i.ImageUrl AS [ImageUrl], i.Qty AS [Qty], i.UnitPriceCents AS [UnitPriceCents], i.LineTotalCents AS [LineTotalCents] FROM (SELECT TOP 2147483647 * FROM order_items WHERE OrderId = o.Id ORDER BY Id) AS i FOR JSON PATH, INCLUDE_NULL_VALUES) AS ItemsJson FROM orders AS o JOIN payments AS p ON p.Id = (SELECT TOP 1 Id FROM payments WHERE OrderId = o.Id ORDER BY Id DESC) WHERE o.Status = 'pending' AND o.PaymentStatus = 'pending' AND p.Status = 'pending' AND NOT p.ConnectPaymentId IS NULL AND o.CreatedAt < DATEADD(MINUTE, -" + str(RECHECK_AFTER_MINUTES) + ', SYSUTCDATETIME()) ORDER BY p.UpdatedAt ASC, o.Id ASC;']
return '\n'.join(parts)
